-- Dormant direct-integrity module template. Not part of composed80 assembly.
-- Installation is refused by the development artifact loader. Expected rows
-- must be embedded build literals; never populate them from the target catalog.
CREATE SCHEMA zasp_authorization80_ordered_current AUTHORIZATION zasp_discovery_authority;
REVOKE ALL ON SCHEMA zasp_authorization80_ordered_current FROM PUBLIC;

CREATE TABLE zasp_authorization80_ordered_current.registration(
 singleton boolean PRIMARY KEY CHECK(singleton),
 format_version integer NOT NULL CHECK(format_version=1),
 profile_checksum text NOT NULL CHECK(profile_checksum ~ '^[a-f0-9]{64}$'),
 manifest_sha256 text NOT NULL CHECK(manifest_sha256 ~ '^[a-f0-9]{64}$')
);
CREATE TABLE zasp_authorization80_ordered_current.expected(
 kind text NOT NULL,
 identity text NOT NULL,
 fact jsonb NOT NULL CHECK(jsonb_typeof(fact)='object'),
 PRIMARY KEY(kind,identity)
);
ALTER TABLE zasp_authorization80_ordered_current.registration OWNER TO zasp_discovery_authority;
ALTER TABLE zasp_authorization80_ordered_current.expected OWNER TO zasp_discovery_authority;
ALTER TABLE zasp_authorization80_ordered_current.registration ENABLE ROW LEVEL SECURITY;
ALTER TABLE zasp_authorization80_ordered_current.expected ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON ALL TABLES IN SCHEMA zasp_authorization80_ordered_current FROM PUBLIC;

CREATE FUNCTION zasp_authorization80_ordered_current.canonical(value jsonb) RETURNS text
LANGUAGE plpgsql IMMUTABLE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $canonical$
DECLARE result text;
BEGIN
 CASE jsonb_typeof(value)
 WHEN 'object' THEN
  SELECT '{'||COALESCE(string_agg(to_jsonb(e.key)::text||':'||zasp_authorization80_ordered_current.canonical(e.value),',' ORDER BY e.key COLLATE "C"),'')||'}'
  INTO result FROM jsonb_each(value) e;
 WHEN 'array' THEN
  SELECT '['||COALESCE(string_agg(zasp_authorization80_ordered_current.canonical(e.value),',' ORDER BY e.ordinality),'')||']'
  INTO result FROM jsonb_array_elements(value) WITH ORDINALITY e;
 WHEN 'number' THEN result:=trim_scale((value#>>'{}')::numeric)::text;
 ELSE result:=value::text;
 END CASE;
 RETURN result;
END
$canonical$;

CREATE FUNCTION zasp_authorization80_ordered_current.normalize_rows(rows jsonb, expected_manifest text) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $normalize$
DECLARE provenance jsonb; span jsonb;
 result jsonb; body text; start_at integer; end_at integer;
 call_prefix constant text:='zasp_authorization80_ordered_current.require(';
BEGIN
 IF jsonb_typeof(rows)<>'array' OR expected_manifest !~ '^[a-f0-9]{64}$' THEN RETURN NULL; END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(rows) r WHERE r->>'kind'='build')<>1 THEN RETURN NULL; END IF;
 SELECT r->'fact' INTO provenance FROM jsonb_array_elements(rows) r WHERE r->>'kind'='build' AND r->>'identity'='provenance';
 IF provenance IS NULL OR (SELECT array_agg(key ORDER BY key COLLATE "C") FROM jsonb_object_keys(provenance) key)
  IS DISTINCT FROM ARRAY['compiled_source_sha256','contract_sha256','entry_spans','format_version','generator_sha256','module_sha256','pgcrypto','postgres','profile_checksum','purpose','reference_file_sha256']::text[]
  OR provenance->>'format_version'<>'1' OR provenance->>'purpose'<>'development-only'
  OR jsonb_typeof(provenance->'entry_spans')<>'array' OR jsonb_typeof(provenance->'module_sha256')<>'array'
  OR jsonb_array_length(provenance->'module_sha256')=0 THEN RETURN NULL; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_each(provenance) p WHERE p.value='null'::jsonb)
  OR EXISTS(SELECT 1 FROM unnest(ARRAY['compiled_source_sha256','contract_sha256','generator_sha256','profile_checksum','reference_file_sha256']) k WHERE provenance->>k !~ '^[a-f0-9]{64}$') THEN RETURN NULL; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(rows) r GROUP BY r->>'kind',r->>'identity' HAVING count(*)<>1) THEN RETURN NULL; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(rows) r WHERE jsonb_typeof(r)<>'object'
  OR (SELECT array_agg(key ORDER BY key COLLATE "C") FROM jsonb_object_keys(r) key) IS DISTINCT FROM ARRAY['fact','identity','kind']::text[]
  OR jsonb_typeof(r->'fact') IS DISTINCT FROM 'object' OR jsonb_typeof(r->'identity') IS DISTINCT FROM 'string' OR jsonb_typeof(r->'kind') IS DISTINCT FROM 'string') THEN RETURN NULL; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(rows) r WHERE r->>'kind'='registration' AND r->>'identity'='["private-registration","zasp_authorization80_ordered_current.registration"]'
  AND r->'fact'->>'manifest_sha256' IS DISTINCT FROM expected_manifest) THEN RETURN NULL; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(provenance->'entry_spans') e GROUP BY (e::jsonb)->>'identity' HAVING count(*)<>1) THEN RETURN NULL; END IF;
 -- Only the finite entry-span list needs procedural validation. Ordinary fact
 -- rows are transformed together below, without recopying a growing JSON array.
 FOR span IN SELECT e::jsonb FROM jsonb_array_elements_text(provenance->'entry_spans') e LOOP
    SELECT r->'fact'->>'definition' INTO body FROM jsonb_array_elements(rows) r WHERE r->>'kind'='routine' AND r->>'identity'=span->>'identity';
    start_at:=(span->>'start')::integer; end_at:=(span->>'end')::integer;
    IF body IS NULL OR octet_length(body)<>length(body) OR start_at<1 OR end_at<>start_at+64
     OR substring(body FROM start_at+1 FOR 64) IS DISTINCT FROM expected_manifest
     OR substring(body FROM start_at-length(call_prefix) FOR length(call_prefix)+1) IS DISTINCT FROM call_prefix||''''
     OR substring(body FROM end_at+1 FOR 2) IS DISTINCT FROM ''')'
     OR length(body)-length(replace(body,call_prefix,''))<>length(call_prefix) THEN RETURN NULL; END IF;
 END LOOP;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('kind',r->>'kind','identity',r->>'identity','fact',
  CASE WHEN r->>'kind'='registration' AND r->>'identity'='["private-registration","zasp_authorization80_ordered_current.registration"]' THEN (r->'fact')-'manifest_sha256'
   WHEN s.value IS NOT NULL THEN jsonb_set(r->'fact','{definition}',to_jsonb(substring(r->'fact'->>'definition' FROM 1 FOR (s.value->>'start')::integer)||'@ordered-current-manifest@'||substring(r->'fact'->>'definition' FROM (s.value->>'end')::integer+1)))
   ELSE r->'fact' END) ORDER BY r->>'kind' COLLATE "C",r->>'identity' COLLATE "C"),'[]'::jsonb)
 INTO result FROM jsonb_array_elements(rows) r LEFT JOIN LATERAL
  (SELECT e::jsonb AS value FROM jsonb_array_elements_text(provenance->'entry_spans') e WHERE r->>'kind'='routine' AND (e::jsonb)->>'identity'=r->>'identity') s ON true;
 RETURN result;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN NULL;
END
$normalize$;

CREATE FUNCTION zasp_authorization80_ordered_current.catalog(expected_manifest text) RETURNS boolean
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $catalog$
DECLARE expected_rows jsonb; normalized jsonb; live_rows jsonb; provenance jsonb;
BEGIN
 IF current_user<>'zasp_discovery_authority' OR expected_manifest IS NULL OR expected_manifest !~ '^[a-f0-9]{64}$' THEN RETURN false; END IF;
 IF (SELECT count(*) FROM zasp_authorization80_ordered_current.registration)<>1 THEN RETURN false; END IF;
 IF NOT EXISTS(SELECT 1 FROM zasp_authorization80_ordered_current.registration WHERE singleton AND format_version=1 AND manifest_sha256=expected_manifest) THEN RETURN false; END IF;
 SELECT jsonb_agg(jsonb_build_object('kind',kind,'identity',identity,'fact',fact) ORDER BY kind COLLATE "C",identity COLLATE "C")
 INTO expected_rows FROM zasp_authorization80_ordered_current.expected;
 normalized:=zasp_authorization80_ordered_current.normalize_rows(expected_rows,expected_manifest);
 IF normalized IS NULL OR encode(pg_catalog.sha256(convert_to(zasp_authorization80_ordered_current.canonical(normalized),'UTF8')),'hex') IS DISTINCT FROM expected_manifest THEN RETURN false; END IF;
 SELECT fact INTO provenance FROM zasp_authorization80_ordered_current.expected WHERE kind='build' AND identity='provenance';
 IF provenance->>'postgres' IS DISTINCT FROM pg_catalog.version() THEN RETURN false; END IF;
 IF NOT EXISTS(SELECT 1 FROM zasp_authorization80_ordered_current.registration WHERE profile_checksum=provenance->>'profile_checksum') THEN RETURN false; END IF;
 -- A partial development manifest cannot admit an evaluator without its own
 -- immutable private closure. Complete reference emission must supply these.
 IF EXISTS(SELECT 1 FROM unnest(ARRAY[
  'zasp_authorization80_ordered_current.canonical(jsonb)',
  'zasp_authorization80_ordered_current.normalize_rows(jsonb,text)',
  'zasp_authorization80_ordered_current.catalog(text)',
  'zasp_authorization80_ordered_current.require(text)']) signature
  WHERE NOT EXISTS(SELECT 1 FROM zasp_authorization80_ordered_current.expected WHERE kind='routine' AND identity='["private-routines",'||to_json(signature)::text||']' AND fact ?& ARRAY['source','binary','sql_body','kind','owner','acl','language','security_definer','volatility','strict','parallel','leakproof','config','returns_set','cost','rows','input_types','all_types','argument_names','argument_modes','argument_defaults','default_count','variadic_type','result_type','support','transforms'])) THEN RETURN false; END IF;
 WITH live AS MATERIALIZED (
  -- ordered-current:direct-collector-begin
WITH direct_column AS MATERIALIZED (SELECT '['||pg_catalog.to_json(c.oid::regclass::text)::text||','||pg_catalog.to_json(a.attnum)::text||']' AS identity, n.nspname::text AS namespace, a.attname::text AS selector_name, c.oid::regclass::text AS selector_relation, c.relname::text AS selector_relation_name, pg_catalog.jsonb_build_object('acl',a.attacl::text,'default',pg_catalog.pg_get_expr(d.adbin,d.adrelid),'default_text_or_empty',COALESCE(pg_catalog.pg_get_expr(d.adbin,d.adrelid),''),'generated',a.attgenerated::text,'identity',a.attidentity::text,'name',a.attname::text,'not_null',a.attnotnull,'position',a.attnum,'relation_name',c.relname::text,'type',pg_catalog.format_type(a.atttypid,a.atttypmod)) AS fact FROM pg_catalog.pg_attribute a JOIN pg_catalog.pg_class c ON c.oid=a.attrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_catalog.pg_attrdef d ON (d.adrelid,d.adnum)=(a.attrelid,a.attnum) WHERE ((n.nspname::text IN('zasp_authorization80_worker') OR false) OR (n.nspname::text IN('zasp_authorization80_runtime') OR false) OR (c.oid::regclass::text='public.zasp_runtime_stage_work') OR (n.nspname::text IN('zasp_authorization80_ordered_current') OR false) OR (c.oid::regclass::text='public.zasp_security_agent_approval_notifications') OR (c.oid::regclass::text='public.zasp_integration_webhook_tests')) AND (a.attnum>0 AND NOT a.attisdropped)),
direct_column_name AS MATERIALIZED (SELECT '['||pg_catalog.to_json(c.oid::regclass::text)::text||','||pg_catalog.to_json(a.attname::text)::text||']' AS identity, n.nspname::text AS namespace, a.attname::text AS selector_name, c.oid::regclass::text AS selector_relation, c.relname::text AS selector_relation_name, pg_catalog.jsonb_build_object('acl_text_or_empty',COALESCE(a.attacl::text,''),'default_text_or_empty',COALESCE(pg_catalog.pg_get_expr(d.adbin,d.adrelid),''),'generated',a.attgenerated::text,'identity',a.attidentity::text,'name',a.attname::text,'normalized_position',CASE WHEN a.attrelid='public.zasp_runtime_candidate_observations'::regclass AND a.attname='sandbox_id' THEN (SELECT pg_catalog.count(*) FROM pg_catalog.pg_attribute live WHERE live.attrelid=a.attrelid AND live.attnum>0 AND live.attnum<=a.attnum AND NOT live.attisdropped) ELSE a.attnum END,'not_null',a.attnotnull,'relation',c.oid::regclass::text,'type',pg_catalog.format_type(a.atttypid,a.atttypmod)) AS fact FROM pg_catalog.pg_attribute a JOIN pg_catalog.pg_class c ON c.oid=a.attrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_catalog.pg_attrdef d ON (d.adrelid,d.adnum)=(a.attrelid,a.attnum) WHERE (((c.oid::regclass::text='public.zasp_runtime_candidate_observations') OR (c.oid::regclass::text='public.zasp_runtime_candidate_snapshots')) OR (c.oid::regclass::text='public.zasp_runtime_session_summaries') OR (c.oid::regclass::text='public.zasp_runtime_session_search_outbox') OR (c.oid::regclass::text='public.zasp_red_team_attempts')) AND (a.attnum>0 AND NOT a.attisdropped)),
direct_constraint AS MATERIALIZED (SELECT '['||pg_catalog.to_json(c.oid::regclass::text)::text||','||pg_catalog.to_json(k.conname::text)::text||']' AS identity, n.nspname::text AS namespace, k.conname::text AS selector_name, c.oid::regclass::text AS selector_relation, c.relname::text AS selector_relation_name, pg_catalog.jsonb_build_object('constraint_type',k.contype::text,'deferrable',k.condeferrable,'deferred',k.condeferred,'definition',pg_catalog.pg_get_constraintdef(k.oid),'definition_pretty',pg_catalog.pg_get_constraintdef(k.oid,true),'name',k.conname::text,'no_inherit',k.connoinherit,'relation',k.conrelid::regclass::text,'validated',k.convalidated) AS fact FROM pg_catalog.pg_constraint k JOIN pg_catalog.pg_class c ON c.oid=k.conrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE ((n.nspname::text IN('zasp_authorization80_worker') OR false) OR (n.nspname::text IN('zasp_authorization80_runtime') OR false) OR (n.nspname::text IN('zasp_authorization80_ordered_current') OR false) OR ((c.oid::regclass::text='public.zasp_runtime_candidate_observations') OR (c.oid::regclass::text='public.zasp_runtime_candidate_snapshots')) OR (c.oid::regclass::text='public.zasp_runtime_session_summaries') OR (c.oid::regclass::text='public.zasp_runtime_session_search_outbox') OR (c.oid::regclass::text='public.zasp_security_agent_approval_notifications') OR (c.oid::regclass::text='public.zasp_integration_webhook_tests') OR (c.oid::regclass::text='public.zasp_red_team_attempts'))),
direct_fixed_runtime_profile AS MATERIALIZED (SELECT '['||pg_catalog.to_json('zasp_authorization80.runtime_profile'::text)::text||','||pg_catalog.to_json(s.singleton)::text||']' AS identity, 'zasp_authorization80'::text AS namespace, pg_catalog.jsonb_build_object('name',s.name::text,'singleton',s.singleton) AS fact FROM zasp_authorization80.runtime_profile s WHERE (('zasp_authorization80'::text IN('zasp_authorization80') OR false))),
direct_global_constraint AS MATERIALIZED (SELECT '['||pg_catalog.to_json(k.conrelid::regclass::text)::text||','||pg_catalog.to_json(k.conname::text)::text||']' AS identity, n.nspname::text AS namespace, k.conname::text AS selector_name, k.conrelid::regclass::text AS selector_relation, c.relname::text AS selector_relation_name, pg_catalog.jsonb_build_object('definition_pretty',pg_catalog.pg_get_constraintdef(k.oid,true),'name',k.conname::text,'relation',k.conrelid::regclass::text) AS fact FROM pg_catalog.pg_constraint k LEFT JOIN pg_catalog.pg_class c ON c.oid=k.conrelid LEFT JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE ((((k.conrelid::regclass::text='public.zasp_runtime_sensor_pairings') OR (k.conrelid::regclass::text='public.zasp_runtime_batch_domains')) OR ((k.conname::text='zasp_sensor_kind_identity_v45') OR (k.conname::text='zasp_runtime_batch_source_identity_v45'))))),
direct_index AS MATERIALIZED (SELECT i.indexrelid::regclass::text AS identity, n.nspname::text AS namespace, c.oid::regclass::text AS selector_relation, c.relname::text AS selector_relation_name, pg_catalog.jsonb_build_object('definition',pg_catalog.pg_get_indexdef(i.indexrelid),'exclusion',i.indisexclusion,'live',i.indislive,'name',index_class.relname::text,'primary',i.indisprimary,'ready',i.indisready,'unique',i.indisunique,'valid',i.indisvalid) AS fact FROM pg_catalog.pg_index i JOIN pg_catalog.pg_class c ON c.oid=i.indrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace JOIN pg_catalog.pg_class index_class ON index_class.oid=i.indexrelid WHERE ((n.nspname::text IN('zasp_authorization80_runtime') OR false) OR (n.nspname::text IN('zasp_authorization80_ordered_current') OR false) OR ((c.oid::regclass::text='public.zasp_runtime_candidate_observations') OR (c.oid::regclass::text='public.zasp_runtime_candidate_snapshots')) OR (c.oid::regclass::text='public.zasp_security_agent_approval_notifications') OR (c.oid::regclass::text='public.zasp_integration_webhook_tests'))),
direct_index_view AS MATERIALIZED (SELECT '['||pg_catalog.to_json(v.schemaname::text)::text||','||pg_catalog.to_json(v.tablename::text)::text||','||pg_catalog.to_json(v.indexname::text)::text||']' AS identity, v.schemaname::text AS namespace, v.indexname::text AS selector_name, v.schemaname::text||'.'||v.tablename::text AS selector_relation, v.tablename::text AS selector_relation_name, v.tablename::text AS selector_table_name, pg_catalog.jsonb_build_object('definition',v.indexdef::text,'name',v.indexname::text) AS fact FROM pg_catalog.pg_indexes v WHERE (((v.schemaname::text='public') AND (v.tablename::text='zasp_runtime_session_summaries')) OR ((v.schemaname::text='public') AND (v.tablename::text='zasp_runtime_session_search_outbox')))),
direct_information_column AS MATERIALIZED (SELECT '['||pg_catalog.to_json(v.table_schema::text)::text||','||pg_catalog.to_json(v.table_name::text)::text||','||pg_catalog.to_json(v.column_name::text)::text||']' AS identity, v.table_schema::text AS namespace, v.column_name::text AS selector_name, v.table_schema::text||'.'||v.table_name::text AS selector_relation, v.table_name::text AS selector_relation_name, v.table_name::text AS selector_table_name, pg_catalog.jsonb_build_object('data_type',v.data_type::text,'default_text_or_empty',COALESCE(v.column_default::text,''),'is_nullable',v.is_nullable::text,'name',v.column_name::text,'relation_name',v.table_name::text) AS fact FROM information_schema.columns v WHERE (((v.table_schema::text='public') AND ((v.table_name::text='zasp_runtime_sensor_pairings') OR (v.table_name::text='zasp_runtime_batch_domains'))))),
direct_membership AS MATERIALIZED (SELECT '['||pg_catalog.to_json(m.roleid::regrole::text)::text||','||pg_catalog.to_json(m.member::regrole::text)::text||','||pg_catalog.to_json(m.grantor::regrole::text)::text||']' AS identity, m.roleid::regrole::text AS namespace, m.member::regrole::text AS selector_member, pg_catalog.jsonb_build_object('admin',m.admin_option) AS fact FROM pg_catalog.pg_auth_members m WHERE ((m.roleid::regrole::text='zasp_temporal_accounting' OR m.member::regrole::text IN('zasp_temporal_executor','zasp_temporal_compensation','zasp_temporal_accounting')))),
direct_namespace AS MATERIALIZED (SELECT n.nspname::text AS identity, n.nspname::text AS namespace, n.nspname::text AS selector_name, pg_catalog.jsonb_build_object('acl',n.nspacl::text,'owner',n.nspowner::regrole::text) AS fact FROM pg_catalog.pg_namespace n WHERE ((n.nspname::text IN('zasp_authorization80_worker') OR false) OR (n.nspname::text IN('zasp_authorization80_runtime') OR false) OR (n.nspname::text IN('zasp_authorization80_ordered_current') OR false))),
direct_policy AS MATERIALIZED (SELECT '['||pg_catalog.to_json(c.oid::regclass::text)::text||','||pg_catalog.to_json(p.polname::text)::text||']' AS identity, n.nspname::text AS namespace, p.polname::text AS selector_name, c.oid::regclass::text AS selector_relation, c.relname::text AS selector_relation_name, pg_catalog.jsonb_build_object('check',pg_catalog.pg_get_expr(p.polwithcheck,p.polrelid),'check_text_or_empty',COALESCE(pg_catalog.pg_get_expr(p.polwithcheck,p.polrelid),''),'command',p.polcmd::text,'name',p.polname::text,'permissive',p.polpermissive,'roles',p.polroles::regrole[]::text,'roles_csv_public_sorted',COALESCE((SELECT pg_catalog.string_agg(CASE WHEN role_oid=0 THEN 'PUBLIC' ELSE role_row.rolname END,',' ORDER BY CASE WHEN role_oid=0 THEN 'PUBLIC' ELSE role_row.rolname END) FROM pg_catalog.unnest(p.polroles) role_oid LEFT JOIN pg_catalog.pg_roles role_row ON role_row.oid=role_oid),''),'roles_named_array_text',ARRAY(SELECT role_row.rolname FROM pg_catalog.pg_roles role_row WHERE role_row.oid=ANY(p.polroles) ORDER BY role_row.rolname)::text,'using',pg_catalog.pg_get_expr(p.polqual,p.polrelid),'using_text_or_empty',COALESCE(pg_catalog.pg_get_expr(p.polqual,p.polrelid),'')) AS fact FROM pg_catalog.pg_policy p JOIN pg_catalog.pg_class c ON c.oid=p.polrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE ((n.nspname::text IN('zasp_authorization80_worker') OR false) OR (n.nspname::text IN('zasp_authorization80_runtime') OR false) OR (c.oid::regclass::text='public.zasp_runtime_stage_work') OR (n.nspname::text IN('zasp_authorization80_ordered_current') OR false) OR (c.oid::regclass::text='public.zasp_security_agent_approval_notifications') OR (c.oid::regclass::text='public.zasp_integration_webhook_tests'))),
