SELECT 'routine'::text AS kind, '['||pg_catalog.to_json('product:red_team_artifacts:function'::text)::text||','||pg_catalog.to_json(identity)::text||']' AS identity, pg_catalog.jsonb_build_object('acl_text_or_empty',fact->'acl_text_or_empty','config_text_or_empty',fact->'config_text_or_empty','definition',fact->'definition','identity_arguments',fact->'identity_arguments','name',fact->'name','owner',fact->'owner','security_definer',fact->'security_definer') AS fact FROM direct_routine WHERE (((namespace='public') AND ((selector_name='zasp_production_red_team_artifacts_readiness') OR (selector_name='zasp_production_red_team_artifacts_security_ready') OR (selector_name='zasp_red_team_valid_input_artifact') OR (selector_name='zasp_red_team_finish_run') OR (selector_name='zasp_red_team_finish_run_v38') OR (selector_name='zasp_red_team_get_run'))))
UNION ALL
SELECT 'constraint'::text AS kind, '['||pg_catalog.to_json('product:red_team_artifacts:constraint'::text)::text||','||pg_catalog.to_json(identity)::text||']' AS identity, pg_catalog.jsonb_build_object('definition',fact->'definition','name',fact->'name','validated',fact->'validated') AS fact FROM direct_constraint WHERE ((selector_relation='public.zasp_red_team_attempts'))
UNION ALL
SELECT 'column_name'::text AS kind, '['||pg_catalog.to_json('product:red_team_artifacts:column'::text)::text||','||pg_catalog.to_json(identity)::text||']' AS identity, pg_catalog.jsonb_build_object('name',fact->'name','not_null',fact->'not_null','type',fact->'type') AS fact FROM direct_column_name WHERE ((selector_relation='public.zasp_red_team_attempts'))
UNION ALL
SELECT 'routine'::text AS kind, '['||pg_catalog.to_json('product:red_team_invocation:function'::text)::text||','||pg_catalog.to_json(identity)::text||']' AS identity, pg_catalog.jsonb_build_object('acl_text_or_empty',fact->'acl_text_or_empty','config_text_or_empty',fact->'config_text_or_empty','definition',fact->'definition','identity_arguments',fact->'identity_arguments','name',fact->'name','owner',fact->'owner','security_definer',fact->'security_definer') AS fact FROM direct_routine WHERE (((namespace='public') AND (selector_name='zasp_production_red_team_invocation_security_ready')))
UNION ALL
SELECT 'routine'::text AS kind, '['||pg_catalog.to_json('product:red_team_safety:function'::text)::text||','||pg_catalog.to_json(identity)::text||']' AS identity, pg_catalog.jsonb_build_object('acl_text_or_empty',fact->'acl_text_or_empty','config_text_or_empty',fact->'config_text_or_empty','definition',fact->'definition','identity_arguments',fact->'identity_arguments','name',fact->'name','owner',fact->'owner','security_definer',fact->'security_definer') AS fact FROM direct_routine WHERE (((namespace='public') AND (selector_name='zasp_production_red_team_safety_security_ready')))
UNION ALL
SELECT 'routine'::text AS kind, '['||pg_catalog.to_json('product:workflow_compatibility:function'::text)::text||','||pg_catalog.to_json(identity)::text||']' AS identity, pg_catalog.jsonb_build_object('acl_text_or_empty',fact->'acl_text_or_empty','config_text_or_empty',fact->'config_text_or_empty','definition',fact->'definition','identity_arguments',fact->'identity_arguments','name',fact->'name','owner',fact->'owner','security_definer',fact->'security_definer') AS fact FROM direct_routine WHERE (((namespace='public') AND ((selector_name='zasp_workflow_mutate') OR (selector_name='zasp_risk_mutate'))))
UNION ALL
SELECT 'fixed_runtime_profile'::text AS kind, '['||pg_catalog.to_json('role-profile:current-profile'::text)::text||','||pg_catalog.to_json(identity)::text||']' AS identity, pg_catalog.jsonb_build_object('name',fact->'name','singleton',fact->'singleton') AS fact FROM direct_fixed_runtime_profile WHERE ((namespace IN('zasp_authorization80') OR false))
UNION ALL
SELECT 'role'::text AS kind, '['||pg_catalog.to_json('role-profile:native-roles'::text)::text||','||pg_catalog.to_json(identity)::text||']' AS identity, pg_catalog.jsonb_build_object('bypass_rls',fact->'bypass_rls','create_db',fact->'create_db','create_role',fact->'create_role','login',fact->'login','replication',fact->'replication','superuser',fact->'superuser') AS fact FROM direct_role WHERE (((selector_name='zasp_temporal_executor') OR (selector_name='zasp_temporal_compensation') OR (selector_name='zasp_temporal_accounting')))
  -- ordered-current:direct-collector-end
 ) SELECT COALESCE(jsonb_agg(jsonb_build_object('kind',kind,'identity',identity,'fact',fact) ORDER BY kind COLLATE "C",identity COLLATE "C"),'[]'::jsonb)
 INTO live_rows FROM live;
 -- Exactly the validated reserved key joins live facts for normalization.
 live_rows:=live_rows||jsonb_build_array(jsonb_build_object('kind','build','identity','provenance','fact',provenance));
 live_rows:=zasp_authorization80_ordered_current.normalize_rows(live_rows,expected_manifest);
 RETURN live_rows IS NOT NULL AND live_rows=normalized;
END
$catalog$;

CREATE FUNCTION zasp_authorization80_ordered_current.require(expected_manifest text) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $require$
BEGIN
 IF zasp_authorization80_ordered_current.catalog(expected_manifest) IS DISTINCT FROM true THEN
  RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered current integrity refused';
 END IF;
END
$require$;

ALTER FUNCTION zasp_authorization80_ordered_current.canonical(jsonb) OWNER TO zasp_discovery_authority;
ALTER FUNCTION zasp_authorization80_ordered_current.normalize_rows(jsonb,text) OWNER TO zasp_discovery_authority;
ALTER FUNCTION zasp_authorization80_ordered_current.catalog(text) OWNER TO zasp_discovery_authority;
ALTER FUNCTION zasp_authorization80_ordered_current.require(text) OWNER TO zasp_discovery_authority;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA zasp_authorization80_ordered_current FROM PUBLIC;
-- Default ACLs may have granted a non-PUBLIC role access at creation. Strip
-- those grants only from the just-created private objects; leave defaults and
-- every original schema untouched. Independent admission still verifies ACLs.
DO $private_acl$
DECLARE target record;
BEGIN
 FOR target IN
  SELECT DISTINCT objects.object_kind,objects.identity,grants.grantee::regrole::text AS grantee
  FROM (
   SELECT 'SCHEMA'::text AS object_kind,pg_catalog.quote_ident(n.nspname) AS identity,n.nspowner AS owner,n.nspacl AS acl
   FROM pg_catalog.pg_namespace n WHERE n.nspname='zasp_authorization80_ordered_current'
   UNION ALL
   SELECT 'TABLE',pg_catalog.format('%I.%I',n.nspname,c.relname),c.relowner,c.relacl
   FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
   WHERE n.nspname='zasp_authorization80_ordered_current' AND c.relkind='r'
   UNION ALL
   SELECT 'FUNCTION',pg_catalog.format('%I.%I(%s)',n.nspname,p.proname,pg_catalog.pg_get_function_identity_arguments(p.oid)),p.proowner,p.proacl
   FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace
   WHERE n.nspname='zasp_authorization80_ordered_current'
  ) objects CROSS JOIN LATERAL pg_catalog.aclexplode(objects.acl) grants
  WHERE grants.grantee<>0 AND grants.grantee<>owner
 LOOP
  EXECUTE pg_catalog.format('REVOKE ALL ON %s %s FROM %s',target.object_kind,target.identity,target.grantee);
 END LOOP;
END
$private_acl$;
-- Reference-only: both private tables remain empty.
